    actions: [{"name": "Bite", "desc": "Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 12 (2d8 + 3) piercing damage.", "attack_bonus": 3, "damage": [{"damage_type": {"index": "piercing", "name": "Piercing", "url": "/api/2014/damage-types/piercing"}, "damage_dice": "2d8+3"}]}, {"name": "Claws", "desc": "Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) slashing damage. If the target is a creature other than an undead, it must succeed on a DC 10 Constitution saving throw or be paralyzed for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.", "attack_bonus": 5, "damage": [{"damage_type": {"index": "slashing", "name": "Slashing", "url": "/api/2014/damage-types/slashing"}, "damage_dice": "2d6+3"}]}],
